SELECT a.qa_id, a.session_id, a.chat_log_id, a.question, a.standard_question, a.answer, a.confidence_score, a.response_time, a.chunk_count, a.user_feedback, a.feedback_reason, a.feedback_type, a.feedback_time, a.tenant_id, a.bot_id, a.creator_id, a.created_time, a.updated_time, a.status_cd FROM bt_dc_qa_record a WHERE a.status_cd = '00A'
AND a.tenant_id = #{query.tenantId}
AND EXISTS ( SELECT 1 FROM bt_dc_qa_record_kb_rel b JOIN bt_knowledge_base c ON c.knowledge_id = b.kb_id AND c.status_cd = '00A'
AND c.tenant_id = #{query.tenantId}
WHERE b.qa_id = a.qa_id AND b.status_cd = '00A'
AND c.space_id = #{query.spaceId}
AND b.kb_id IN (#{id})
AND ( c.owner_id = #{query.userId} OR c.knowledge_id IN ( SELECT bp.kb_id FROM bt_dc_kb_permission bp WHERE bp.permission_type = 'MANAGE' AND bp.status_cd = '00A' AND ( (bp.subject_type = 'USER' AND bp.subject_id = #{query.userId})
OR (bp.subject_type = 'ORG' AND bp.subject_id IN (#{id}))
) ) )
) ORDER BY a.created_time DESC

SELECT DISTINCT a.qa_id, a.confidence_score, a.chunk_count, a.user_feedback, a.created_time FROM bt_dc_qa_record a,bt_dc_qa_record_kb_rel b WHERE a.qa_id = b.qa_id AND a.status_cd='00A'
AND a.created_time >= #{query.startTime}
AND a.created_time <= #{query.endTime}
AND b.kb_id IN(#{id})
ORDER BY a.created_time DESC

SELECT COUNT(DISTINCT a.qa_id) as questionsAndAnswersTotal, CASE WHEN COUNT(DISTINCT a.qa_id) = 0 THEN 0.00 ELSE ROUND(AVG(a.confidence_score) * 100, 2) END as hitRate, SUM(CASE WHEN a.user_feedback = 'LIKE' THEN 1 ELSE 0 END) as numberOfLikesTotal, SUM(CASE WHEN a.user_feedback = 'DISLIKE' THEN 1 ELSE 0 END) as stepTotal, COUNT(DISTINCT a.creator_id) as questionAnswerUserTotal,
COUNT(CASE WHEN a.user_feedback = 'DISLIKE' AND a.feedback_reason IS NOT NULL AND dbms_lob.getlength(a.feedback_reason) > 0 THEN 1 END) as feedbackReasonCount
COUNT(CASE WHEN a.user_feedback = 'DISLIKE' AND a.feedback_reason IS NOT NULL AND a.feedback_reason != '' THEN 1 END) as feedbackReasonCount
FROM bt_dc_qa_record a, bt_dc_qa_record_kb_rel b, bt_knowledge_base c LEFT JOIN bt_dc_kb_permission bp ON c.knowledge_id = bp.kb_id AND bp.status_cd = '00A' WHERE a.qa_id = b.qa_id AND c.knowledge_id = b.kb_id AND c.status_cd = '00A' and c.tenant_id = a.tenant_id AND a.status_cd = '00A'
AND a.created_time >= #{query.startTime}
AND a.created_time <= #{query.endTime}
AND a.tenant_id = #{query.tenantId}
AND c.space_id = #{query.spaceId}
AND b.kb_id IN(#{id})
AND ( c.owner_id = #{query.userId} OR (bp.permission_type ='MANAGE' AND bp.subject_type = 'USER' AND bp.subject_id = #{query.userId})
OR (bp.permission_type ='MANAGE' AND bp.subject_type = 'ORG' AND bp.subject_id IN (#{id}))
)

